package net.civeira.phylax.feature.template.themeversion.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.template.themeversion.domain.ThemeVersion;
import net.civeira.phylax.feature.template.themeversion.domain.valueobject.ContentTextVO;

class ContentTextValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of content text of theme version")
  void test_content_text_value_holder_assign_plain_value() {
    Object holder = new Object();
    ContentTextValueHolder<Object> value = new ContentTextValueHolder<>(holder);
    Assertions.assertSame(holder, value.contentText("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getContentTextValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getContentText().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.contentTextNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getContentTextValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getContentText().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of content text of theme version")
  void test_content_text_value_holder_assign_value_object() {
    Object holder = new Object();
    ContentTextValueHolder<Object> value = new ContentTextValueHolder<>(holder);
    ContentTextVO vo = ContentTextVO.from("one");
    Assertions.assertFalse(value.getContentTextValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.contentText(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getContentTextValue().orElseThrow());
    Assertions.assertSame(holder, value.contentText(Optional.empty()));
    Assertions.assertFalse(value.getContentTextValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.contentText(Optional.of(vo)));
    Assertions.assertSame(vo, value.getContentTextValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of content text of theme version against the original")
  void test_content_text_value_holder_read() {
    Object holder = new Object();
    ContentTextValueHolder<Object> value = new ContentTextValueHolder<>(holder);
    ContentTextVO vo = ContentTextVO.from("one");
    ContentTextVO other = ContentTextVO.from("one");
    ThemeVersion original = Mockito.mock(ThemeVersion.class);
    Mockito.when(original.getContentTextValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readContentText(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readContentText(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.contentText(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readContentText(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readContentText(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of content text of theme version")
  void test_content_text_value_holder_unset() {
    Object holder = new Object();
    ContentTextValueHolder<Object> value = new ContentTextValueHolder<>(holder);
    ContentTextVO vo = ContentTextVO.from("one");
    value.contentText(vo);
    Assertions.assertSame(holder, value.unsetContentTextIfMatches("contentText_other"));
    Assertions.assertTrue(value.getContentTextValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetContentTextIfMatches("contentText"));
    Assertions.assertFalse(value.getContentTextValue().isPresent(),
        "The field name must clear the value");
    value.contentText(vo);
    Assertions.assertSame(holder, value.unsetContentText());
    Assertions.assertFalse(value.getContentTextValue().isPresent(), "Unset must clear the value");
  }
}
